      "assessment": "１．あらゆる年齢の人の健康的な生活、２．健康を支える福祉、３．疾病及び介護予防、４．人の健康維持のための福祉の役割や支援\n上記１～４に関する理解度を以下の「学生に対する評価」により評価する。",
