        "疾病による身体的状況と特徴 事前：年代別に見る疾病による身体的特徴を調べる（2時間） 事後：講義で学んだ事をノート、プリントなどで振り返る（2時間）",
        "疾病による精神的状況と特徴 事前：年代別に見る疾病による精神的特徴を調べる（2時間） 事後：講義で学んだ事をノート、プリントなどで振り返る（2時間）",
