      "summary": "周南・周防の地理や防災、藩政と地域史、明治維新、産業、ゆかりの人物や文化人を題材に、地域の成り立ちと文化を学ぶ。地域の歴史的背景を理解したうえで自ら調査・考察し、周南の将来や地域再生について発信する力を養う。",
      "sourceUrl": "https://aaaweb.shunan-u.ac.jp/aa_web/syllabus/se0032.aspx?me=EU&opi=mt0010&sk=2026_2_1012100A&syw=1",
      "themeAndGoals": "毎回のテーマに沿って周南の地理・歴史・文化についての研究専門家をお招きし、現在の周南に繋がるさまざ\nまな功績をわかりやすく説明していただきます。\n【到達目標】\n(i) 周南地域再生を担う人材として周南の地理・歴史・文化についての基礎知識を得ることが出来る。\n(ii) これらの知識を踏まえ、周南地域の将来について自ら調査・考察し発信することができる。",
      "officialOverview": "本学は、地域の課題解決に資する様々な人材や情報・技術が集まる、地域コミュニティの中核的存在としての活動する「地（知）の拠点」（COC）構想を展開している。本授業では、この趣旨を理解し、その一員として学生が活動できるようになるために、自治体と連携し、学生が主体的に教育・研究・地域貢献を進めるための基礎的な知識を身につけることを目的とする。とりわけ、周南地域について深い見識を有する、歴史博物館の関係者や学校関係者などを講師に招き、「周南地域の地理的特色と防災」「周防の国を治めた武将たち」「明治維新と周南地域」「周南をはじめとする周防の国にゆかりの文化人たち」といったテーマについて理解を深める。",
