    "1012700A": {
      "name": "人の健康生活",
      "summary": "健康を身体・心理・社会の側面から捉え、子どもの健康、障がいのある人の暮らし、性と生殖の健康、ストレス対処、セルフケアや支援環境を学ぶ。健康に影響する要因や多様な価値観を理解し、一人ひとりらしい豊かな生活を考察して支援の視点を持つ力を養う。",
      "sourceUrl": "https://aaaweb.shunan-u.ac.jp/aa_web/syllabus/se0032.aspx?me=EU&opi=mt0010&sk=2026_2_1012700A&syw=1",
      "themeAndGoals": "１．人及び人の健康の捉え方を知る。\n２．人の多様な健康生活を知る。\n３．人の健康に影響を及ぼす影響や要因を説明できる。\n４．人の健康に関する価値やその人らしい健康生活の考え方を説明できる。\n５．人の健康生活に関するトピックに関して参考文献等を用いて考察できる。",
      "officialOverview": "病気や障がいの有無にかかわらず、あらゆる健康状態にある人びとの健康を身体的、精神的、社会的側面から捉えることは、一人ひとりの人間の、その人らしくより豊かな生活健康を考える重要な視点である。本授業では人の健康生活について、人間を全人的に理解し、健康を身体的側面、精神的側面、社会的側面から理解することを通して、人の健康生活のための知識とスキルを理解する。本授業を通して、人の健康に影響を及ぼす環境や要因、人の健康に関する価値、その人らしいより豊かな健康生活に関する考え方の基礎的知識を身につける。",
      "teachingMethod": "■ 講義　□ 演習　□ 実験・実習・実技",
      "teachingFormat": "■ 対面　□ ﾊｲﾌﾚｯｸｽ　□ オンライン　□ オンデマンド",
      "assessment": "課題レポート100％\n4人の教員が担当した授業内容から、関心を持った授業内容に関するテーマで課題レポートを作成する。\n字数：600～800字（文献を適切に引用する。文献は文字数に含まない）\n課題レポートのタイトルに教員名（姓のみ）を記載する。\nレポートはTeamsの「人の健康生活」のチームに各教員名のフォルダにアップロードして提出してください。\nレポート締め切り期日：2024年11月20日（水）18時",
      "lessonPlan": [
        "ガイダンス、全人的な人の捉え方と人の健康生活",
        "セクシュアルリプロダクティブヘルス/ライツ（SRHR）",
        "疾病や障がいの有無に関わらず子どもが健康に暮らす①",
        "疾病や障がいの有無に関わらず子どもが健康に暮らす②",
        "病気や障がいがある人の健康生活とソーシャルサポート",
        "人の生活におけるストレスとコーピング",
        "セルフケア、ヘルスプロモーション",
        "総括"
      ]
    },
