      "officialOverview": "Each week, students will be asked to write an email to a prospective client. These emails will be exchanged with other students to practice replying. There will be a focus on written grammar using business proposals and covering letters.\nHomework will be assigned each week to prepare for the following lesson. This homework is important for class participation, with is half of the grade.",
