        "文脈③ライフステージ・時代・文化",
        "因果②Well-beingを左右するミクロ・マクロの要因",
        "中盤の総括 過去の問題の検討",
        "構想①現代のWell-beingのデザイン",
        "構想②誰の問題なのか その介入可能性",
