      "themeAndGoals": "１．精神保健に関する基本概念を説明できる。\n２．現代社会における、精神的諸問題について説明できる。\n３．メンタルヘルスを維持する方法、ストレス対処について説明できる。\n４. 自己理解、他者理解における精神保健的、臨床心理学的考え方を知る。",
      "officialOverview": "現代社会は多くのストレスにさらされ、メンタルヘルスの危機に直面しやすい。本授業では、こころの健康、こころの健康の維持、こころの病気の予防、日々の生活とストレス、ストレス因子と対処法、主なこころの病気等、精神保健にかかわる問題解決に必要な基礎的知識を理解する。本授業を通して、現代社会における精神的健康にかかわる諸課題、こころの健康の維持、ストレス対処に関する基礎的知識を身につける。",
