        "「身体トレーニング➀」 トレーニングの重要性とトレーニングの原則 運動処方 健康づくりのための身体活動・運動ガイド",
        "「身体トレーニング➁」 有酸素運動のトレーニング効果 ダイエット大作戦",
        "「身体トレーニング➂」 レジスタンストレーニングなどの目的と効果 ストレッチングの運動処方",
        "「スポーツ外傷とスポーツ障害」 運動中のケガや使い過ぎ症候群について 応急処置（RICE処置）",
        "「生活習慣病とその予防」 生活習慣病の要因 健康的なライフスタイルについて 講義の総括"
