      "assessment": "①社会起業家について理解している\n②課題認識と構造分析を理解している\n③フィールドワークを通じ、マーケティングの概念を理解している\n④納得、共感を得るプレゼンテーション資料の作成と発表ができる\n⑤クラスワーク（ポートフォリオ、発言、フィールドワーク）に積極的に取り組んでいる",
