      "summary": "日常生活に関わる金融、企業統治、経済行動や意思決定、地域コミュニティ、営利・非営利組織、企業の社会的役割、税制度を幅広く学ぶ。経済・経営の基礎知識を身近な事例に当てはめて考察し、自分や地域の暮らしをより豊かにする方法を提案・実践する力を身につける。",
      "sourceUrl": "https://aaaweb.shunan-u.ac.jp/aa_web/syllabus/se0032.aspx?me=EU&opi=mt0010&sk=2026_2_1100900A&syw=1",
      "themeAndGoals": "【到達目標】\n・日常生活で必要となる、経済・経営に関する基礎知識を修得することができる\n・身の回りのことについて、経済・経営に関する知識を基に考察できるようになる\n・自分自身や地域社会の生活を豊かにする方法を考え、実践できるようになる",
      "officialOverview": "本講義では、経済学や経営学を専門としていない学生でも日常生活を送るうえで必要となる経済学や経営学に関する知識をオムニバス形式で教授する。また、学んだことを踏まえて、最終的にアウトプットする手法についても学び、今後の生活にも活かせるようにする。",
      "teachingMethod": "■ 講義　□ 演習　□ 実験・実習・実技",
      "teachingFormat": "■ 対面　□ ﾊｲﾌﾚｯｸｽ　□ オンライン　□ オンデマンド",
      "assessment": "各回の講義内容についてしっかりと理解し、学習した内容を踏まえて身の回りの経済・社会問題に対して適切に考察できるようになっているのかを総合的に評価する。\n評価は講義後のリアクションペーパーやレポート課題、小テストにて判断する。各回の担当教員の指示をしっかりと聞き対応すること。",
