      "summary": "時制、仮定法、助動詞、不定詞や動名詞などの基礎文法を、音声の聞き取り、音読、速読、語彙学習を通じて学ぶ。日常会話の初歩的な表現と英語論文の概要を理解する力を身につけ、研究や学修に必要な基礎英語を養う。",
      "sourceUrl": "https://aaaweb.shunan-u.ac.jp/aa_web/syllabus/se0032.aspx?me=EU&opi=mt0010&sk=2026_2_1101200A&syw=1",
      "themeAndGoals": "１.情報科学の研究遂行に必要な初歩の英語力を身につけることができる。\n２.日常的な場面の会話において英語で口頭表現することができる。\n３.英語で書かれた論文やレポートのおおよその内容を理解することができる。",
      "officialOverview": "コミュニケーション英語Ⅰ～Ⅳでは、情報科学部における研究遂行に必要な英会話、および英語に関するリーディングとライティング能力、明解な口頭発表を行うためのプレゼンテーション能力、闊達な議論を可能とするコミュニケーション能力を身につける。こうした力は情報科学部における4年間の学びの基礎となるのみならず、卒業後の進路において有用な武器となる。本授業を通じて学生は、情報科学部で必要となる初歩的な英語力（研究遂行のための初歩の英語力、日常な会話力、英語論文の概要を理解する力）を身につける。\n授業はオンデマンド教材を用いたe-learningによって進める。毎回の授業についてLMSを通じて学習すべき教材を指示する。",
