    "1101300A": {
      "name": "アカデミックライティング",
      "summary": "大学レポートの課題読解、書式や文体、段落構成、意見文の型、文献の要約・引用と剽窃防止を学ぶ。結論と根拠を筋道立てて示し、出典を適切に扱ったレポートや改まったメールを作成・推敲する力を身につける。",
      "sourceUrl": "https://aaaweb.shunan-u.ac.jp/aa_web/syllabus/se0032.aspx?me=EU&opi=mt0010&sk=2026_2_1101300A&syw=1",
      "themeAndGoals": "この授業では大学で書く文章（アカデミック・ライティング）の基礎、とりわけ意見を述べるレポートに求められる最低限の体裁の整った文章を作成するスキルの習得を目指す。\n(i) 文章表現・レポート作成に必要な基礎的知識を説明できる\n(ii) やや改まったメールなどに要求される様式に則った簡単な文章の作成ができる\n(iii）レポートに求められる体裁を満たして、意見を主張するレポートを作成できる",
      "officialOverview": "最初に受講者に対して前期期間に他の授業で課されたレポートの課題を振り返り、レポート作成に共通に求められる注意点を確認します。意見を述べる文章の核心となる「結論」⇒「理由」⇒「説明」⇒「結論」の構造を学習の上、最終レポートは3つのレポートの型から選択して作成します。その他必要に応じて、学外者や大学教員とのやり取りを行う際に用いるメール等の文章についても扱います。いずれの文章もPCでの作成を想定しています。\n授業は講義形式で実施します。毎回振り返りを課しその回答をもとに、教員が受講生に質問しながら進行します。\n実施予定の内容は以下の通りです。\n・「課題の要求」の理解。課題文を読み解く\n・レポートの書式（タイトル・番号・氏名）、期限・文字数\n・レポートにふさわしい文体（常体・敬体）\n・原稿用紙の使い方（段落の体裁）\n・段落の作り方（パラグラフ・センテンス）、一文・段落の適正サイズ\n・文章の型\n・剽窃と文献の参照方法\n・文献の読解と要約\n・意見文の作成\n・文章の評価\n・その他、メール・チャットでの文章の作法（授業の進行状況や学生の要望に応じて）\n【注意】\n・授業の進行状況・学生の関心によって授業計画を変更する場合があります。\n・可能な限り毎回の授業で振り返りの提出を求めます。文章表現の授業ですので「特になし」は控えてください。\n・質問された場合には必ず答えてください（「わかりません」は回答とみなしません。正解でなく「どう考えたか？」「なぜそう考えたか？」をしつこく尋ねます。考えることに慣れましょう）。\n・レポート類はPCで作成することを想定しています。",
      "teachingMethod": "■ 講義　□ 演習　□ 実験・実習・実技",
      "teachingFormat": "■ 対面　□ ﾊｲﾌﾚｯｸｽ　□ オンライン　□ オンデマンド",
      "assessment": "レポートおよび提出物（以下、レポート類）により評価します。レポート類は授業内で配布するチェックリスト（またはルーブリック等）に従って採点します。レポート類は形式面80%、内容面20%の割合で評価します。最終課題となるレポートは授業期間内に1度提出し、何等か教員のフィードバックを最低1回受けることを条件とし、試験期間に提出します。",
      "lessonPlan": [
        "・オリエンテーション：アカデミック・ライティングとは",
        "・他の授業でのレポート課題の振返り",
        "・「課題の要求」の理解：課題の指示を読み解く ・レポートに求められる一般的事項",
        "・レポートの書式：タイトル・番号・氏名 ・レポートの期限・文字数 ・レポートにふさわしい文体：常体か敬体か",
        "・原稿用紙の使い方：段落の体裁、禁則 ・文、段落の適正サイズ",
        "・段落の作り方（パラグラフ・ライティングについて）",
        "・レポート点検練習①改善すべき箇所の把握",
        "・レポート点検練習②レポートの改善と振返り",
        "・文章の型のいろいろ ・本授業での意見文の型（結論⇒理由⇒説明⇒結論） ・感想文と意見文の違い等",
        "・定型的な文書の型（メール文）",
        "・剽窃と文献の参照方法（文献表示の作法、参照の作法（略記と註、引用の作法（直接引用と要約））",
        "・適切な参照の練習",
        "・最終レポートの作成①：課題の解説 ・課題の要求の確認 ・レポートチェックリストの確認",
        "・最終レポートの作成②：チェックリスト（ルーブリック）での自己点検 ・レポートの完成と点検",
        "・授業全体の振り返り ・オンライン授業評価"
      ]
    },
