      "sourceUrl": "https://aaaweb.shunan-u.ac.jp/aa_web/syllabus/se0032.aspx?me=EU&opi=mt0010&sk=2026_2_2011500A&syw=1",
      "themeAndGoals": "1. スポーツマネジメントの定義を理解できる。\n2. スポーツマネジメント手法であるスポーツスポンサーシップの構造について理解できる。\n3. 日本のスポーツ政策と行財政制度の基本を理解した上で、公共スポーツ施設管理運営方法の基礎理論を理解できる。\n4. スポーツ企業のブランディング戦略について理解できる。",
      "officialOverview": "スポーツマネジメントは、スポーツ関連事業の促進又はその組織化に関与する人、活動、業務等の研究と実践に関わる理論である。本講義では、スポーツマネジメントの定義と理論を理解した上で、グローバルビッグスポーツイベントとしての近代オリンピック大会マネジメントの歴史的変容とこれがスポーツ界に及ぼした影響について理解する。また、日本のスポーツ政策及び行財政制度を理解した上で、地域スポーツの振興に密接な公共スポーツ施設マネジメントの個別事例を理解する。さらに、世界的なスポーツ企業である NIKE、アディダス、プーマ、コンバース社などの経営史からスポーツ関連企業マネジメントに関する理解を深める。",
      "teachingMethod": "■ 講義　□ 演習　□ 実験・実習・実技",
