      "summary": "人間の自然言語を情報伝達の仕組みとして捉え、音・語・文法・文の意味や曖昧さ、言語に関する無意識の知識を学ぶ。言語データやコーパスを分析して変化・使用傾向を読み取り、自然言語の特徴と他分野や社会での活用を考える基礎力を身につける。",
      "sourceUrl": "https://aaaweb.shunan-u.ac.jp/aa_web/syllabus/se0032.aspx?me=EU&opi=mt0010&sk=2026_2_2025900A&syw=1",
      "themeAndGoals": "1.\t自然言語の分析に関わる形態素、音素など基礎的な用語と仕組みが理解できる\n2.\t自然言語の分析を通して明らかとされている知見について理解できる\n3.\t自然言語の分析を通して明らかにされることと他分野との関連について考えることができる",
      "officialOverview": "コンピュータが理解し、処理を実行するための命令にプログラミング言語が用いられるのに対し、我々人間がコミュニケーションに用いる言語は自然言語と呼ばれます。この自然言語は、日常的に行われる情報伝達には、必要不可欠なものです。本授業では、情報伝達において「自然言語」がどのような役割を果たしているのかを考える上での基本的な知識、考え方を身に付けます。授業では、一般的に、「言語学」と呼ばれる学問について考えていきます。具体的には、私たちの身の回りにある「自然言語」がどのようなものかをゆっくり考えることから始め、自然言語における文法の成り立ち、用語のあり方、自然言語の分析に関わる基礎的な概念、いくつかの研究手法について学びます。その後、自然言語の分析が現在、他分野においてどのように活用されているのかを紹介します。",
      "teachingMethod": "■ 講義　□ 演習　□ 実験・実習・実技",
      "teachingFormat": "■ 対面　□ ﾊｲﾌﾚｯｸｽ　□ オンライン　□ オンデマンド",
      "assessment": "1.\t自然言語の分析に関わる用語や仕組みに関する基本的な知識\n2.\t自然言語の分析結果の活用事例\n3.\t自然言語の分析方法の基本的な知識\n4.\t自然言語の分析\nこれら４つの視点についての理解度を以下の「学生に対する評価」により評価する。\n課題レポート　40%、授業ごとの小課題30％、２回の小レポート30％",
