      "summary": "旅客、製薬、金融、航空、製造、マーケティングなど幅広い業界の事例から、データ活用の目的、扱うデータ、技術、データサイエンティストの役割を学ぶ。データ活用の利点と留意点を理解し、社会や企業の課題にデータ分析がどう役立つかを具体的に説明する力を身につける。",
