      "themeAndGoals": "デジタル社会において、以下の項目を理解する\n1.なぜデータ活用が必要なのか\n2.どのようなデータが使われているのか\n3.データの活用にはどのような技術が使われているのか\n4.データ活用で留意しなくてはならない点",
      "officialOverview": "現代のデジタル社会では、様々な活動にデータが活用されています。皆さんが便利に日常を過ごしている背後には、膨大な量のデータがやりとりされ高度なデジタル技術が活用されています。この講義では、データ活用の実際を幅広い分野の事例を通じ、なぜデータ活用が必要か、どのようなデータが使われているのか、どのような技術が使われているのか、データ活用で留意しなくてはならない点、さらに、データ活用の中心となるデータサイエンティストの活動の実際に関してもお話します。",
