      "name": "計算機概論",
      "summary": "コンピュータの歴史と動作原理を基礎に、デジタル表現、ハードウェア、OS・プログラム、データベース、ネットワーク、AIやクラウドの仕組みを学ぶ。情報倫理やセキュリティも含め、コンピュータシステムの利点と危険性を理解し、社会や生活の中で適切に活用するリテラシーを身につける。",
