    "2101200A": {
      "name": "確率統計基礎",
      "summary": "公理的確率、確率分布、ベイズの定理や中心極限定理を学び、統計の頻度主義・ベイズ的解釈、推定・検定、回帰や因子モデルへ進む。確率計算や統計量の意味を理解し、データの特性に応じて基本的な統計モデルを実データに適用する力を身につける。",
      "sourceUrl": "https://aaaweb.shunan-u.ac.jp/aa_web/syllabus/se0032.aspx?me=EU&opi=mt0010&sk=2026_2_2101200A&syw=1",
      "themeAndGoals": "１．確率論の基本概念を理解し、全確率の公式を利用して確率の計算ができる。\n２．統計学の基本的な考え方を理解し、基本的な統計量の計算および統計モデルを実データに適用することができる。",
      "officialOverview": "本講義では、データ分析や確率モデルの学習のための基礎である確率と統計の基本的な事項について説明する。前半は確率の考え方を公理的確率論の枠組みで説明し、客観確率と主観確率が存在することを理解する。特に、確率計算の際に重要な道具となる全確率の公式の導出および利用について学ぶ。また、統計的推定や検定において中心的な枠割を演じる大数の法則と中心極限定理について説明する。後半は統計学の考え方として頻度主義の解釈とベイズ的解釈が存在することを説明し、問題に応じて使い分けることを理解したうえで、頻度主義に基づく推定と検定方法を説明する。また、説明変数と被説明変数を理解し、この枠組みで回帰モデルやファクターモデルを説明し実データに適用する際の手順を理解する。",
      "teachingMethod": "■ 講義　□ 演習　□ 実験・実習・実技",
      "teachingFormat": "■ 対面　□ ﾊｲﾌﾚｯｸｽ　□ オンライン　□ オンデマンド",
      "assessment": "講義中の中間試験（40点 程度），期末試験（40点程度）その他 講義中のアンケート参加などで 20 点程度の評価とする．",
      "lessonPlan": [
        "ガイダンス、生活の中の確率、確率の捉え方、ラプラスの悪魔、不確実性とリスク",
        "確率基礎：事象、確率測度、確率変数、独立、全確率の公式、ベイズの定理",
        "確率分布：離散分布と連続分布、密度関数と分布関数、多変量分布、平均、分散、標準偏差、相関係数",
        "積率母関数と特性関数、大数の法則",
        "離散分布：ベルヌーイ試行、二項分布、幾何分布、ポアソン分布、小数の法則",
        "連続分布：正規分布、一様分布、指数分布、ｔ分布、逆関数法",
        "正規分布と中心極限定理、多変量正規分布、コレスキー分解",
        "中間試験：確率基礎の復習",
        "統計学の考え方：調査と標本、データ可視化、統計量、標本平均、標本分散、バイアス",
        "推定と検定：点推定、区間推定、大数の法則と中心極限定理",
        "回帰モデル：説明変数と被説明変数、残差、最小二乗法",
        "自己回帰モデル：相関関係と因果関係",
        "ファクターモデルと因子分析",
        "回帰と分類：偽陽性と偽陰性、数量化モデル",
        "判別分析とクラスタリング",
        "期末試験"
      ]
    },
