      "officialOverview": "グローバルな視野をもった人材を目指すために、英語への苦手意識を取り除くことが本講義の主眼で\nある。そのために、英語の基盤的知識・スキルを確認しつつ、既習事項であるデータサイエンスに必要な数学（微分積分・線形代数・確率統計\n等）を英語で解説する。大学数学と英語の教科横断的な視点に立って授業を行い、英語を手段として\n使い数学の教養を深める訓練を行う。主に講義形式で授業を進めていくが、学生との議論も重視した\nい。受講者数次第では学生に英語での発言の機会も提供する。レポート課題を中心に成績を評価する\nが、レポートも全て英語で提出することを前提としている。",
      "teachingMethod": "■ 講義　□ 演習　□ 実験・実習・実技",
