      "themeAndGoals": "1.英語でブロックチェーンとは何かを理解し説明できる。\n2.英語でブロックチェーンに必要な暗号技術を理解し説明できる。\n3.金融業におけるブロックチェーンの活用を考察するために必要な基礎的事項を英語で理解し説明できる。",
      "officialOverview": "先端的な研究・技術を理解するためには英語で発信された情報へのアクセスがきわめて重要である。この視点から、本講義では、ブロックチェーンの金融業への活用を題材に実践的な英語力を身に付ける。具体的には、実在のプロジェクトのWhite paper や新聞記事を用いて、正確さを犠牲にすることなく、速読できることを目指すほか、YouTube に掲載されたカンファレンスの講演記録やインタビュー映像を字幕なしで視聴し、リスニング力を鍛える。さらに、実在のコミュニティが議論を戦わせているTelegram やDiscord 等へアクセスし、文章による実践的コミュニケーション力を向上させることを目標とする。\nなお、これらを実現するために必要な金融や情報科学の基礎知識は既知のものとして扱うが、授業の進行に合わせた予習用教材を提供するほか、ブロックチェーンや暗号に関する知識は適宜解説しながら授業を進める。",
      "teachingMethod": "■ 講義　■ 演習　□ 実験・実習・実技",
