      "officialOverview": "本科目は、ニューラルネットワークに関するものである。ニューラルネットワークは近年のAI技術の進歩の発端となった深層学習が展開されるモデルである。本授業では、歴史的な事柄も含めてニューラルネットワークの基礎を学んだ上で、深層学習を理解することを目標とする。深層学習特有の技術や理論、モデルデザイン手法を解説する。誤差逆伝播アルゴリズムを解説したのち、深層学習特有の技術（初期化、正則化など）、そして、畳み込みニューラルネットワーク、再帰的ニューラルネットワーク、敵対的生成ネットワークなどについて学ぶ。これらを通して、深層学習とはどのようなものであるかを学び、どのような時にどのモデルを使い、どのように評価すれば良いのかといった基礎的な能力を涵養するとともに、実際の問題に応用するに十分な能力を身に付ける。",
