      "officialOverview": "モノをインターネットの接続することでそこから得られるデータを効果的に処理したりモノを制御するフレームワークがIoT (Internet of Things) であるが、単純制御を超えて環境データなどに応じた動的な制御処理を行うことが意図されている点でAIとIoTは表裏一体であり、スマートソサエティなどの実現に欠かせない。本講義ではIoTの目や耳を担うセンサーテクノロジー、複数のモノからのデータを集約し処理する基本的なデータ処理技術、それに基づくアウトプットとしての警告発出やモノの制御について基礎的なレベルを概観し、それがどのように今後のビジネス、社会の向上につなげられるのかをケースステディとして学習することで、AIとIoTの協調で今後のビジネス社会がどのように発展していくかを知り、それを利用・活用する知識・技術の基盤を身に付ける。\n授業では講義形式が中心となるが、実際の活用例をもとにした議論、初歩的なIoT の実装演習を含む。",
