      "officialOverview": "多変量解析とは、多くの情報（複数のデータ）の関連性を分析し、「要約・予測」するための分析手法であり、情報化社会において必須のスキルのひとつである。本講義では、線形代数・微分積分・数理統計等の知識を前提とし、多変量解析の方法を学ぶ。数式を用いた多変量解析の厳密な記述ではなく、多変量解析の本質的な考え方を理解することが主眼となる。また、様々な多変量解析の種類と選択方法を解説し、RやPythonを用いた実践的な手段も紹介する。重回帰分析、判別分析、主成分分析等の代表的な手法の数学的根拠を理解し、実践的な課題に取り組む能力を身につける。主に講義形式で授業を進めていくが、プログラミングを用いた演習等も必要に応じて実施する。",
