      "officialOverview": "人間の言語（自然言語）をコンピュータで扱う自然言語処理はAIの大きな一分野として長い歴史を持つ。自然言語の扱いにはさまざまな困難点があるが、近年の大規模言語モデルの急速な発展により、自然言語処理という学問分野は大きく変貌を遂げつつある。本講義では、基本的な自然言語処理の対象と技術、そしてタスクを概観した上で、機械学習、特にTransformerを用いた深層学習を中心として、その数理・構造を理解することを目的とする。その際、Pythonを用いた部分実装等を含むことで、実践的なスキルを身に付ける。なお、以上のように本科目は自然言語処理という技術的テーマを扱う科目であって、生成AIのプロンプトエンジニアリングなど、ユーザとしての使い方を講じるものではない点、履修申請時に十分留意すること。",
