      "officialOverview": "機械学習と推薦システム（レコメンデーションシステム）に関する講義である。Python入門やAI・機械学習基礎等を学習した受講生を対象に、より実践的で高度なデータ解析の理論や手法、実社会における応用やレコメンデーションの事例について学ぶ。\n講義は主にオンデマンド形式とオンライン形式で実施。座学だけでなく、プログラミング演習の両方を行う。Pythonでのプログラミングの演習を通じて、実社会で行われている情報推薦の処理やアルゴリズム等を修得する。具体的には機械学習や推薦システムの理論的講義の後、サンプルデータを用いながらデータ加工・モデル作成・モデルの評価等、実践に近い方法で授業を進め、理論とプログラミングを修得する。",
