      "officialOverview": "情報エンジニアリング概論は、現在の情報システム（エンタープライズシステム、組み込みシステム、Webシステム等）を、実際に企業ではどのように構築していくのかを体系的に学ぶ学問と位置付ける。\nしたがって、日本で最も企業数が多い製造ビジネスドメインを題材に取り、ビジネスドメインでの情報システムの構造（システムアーキテクチャ）を学習し、システムアーキテクチャのモデリング技術を演習により習得する。\nまた、近年、情報システムの主流となりつつあるクラウド技術、分散システム、コンテナ技術を学習し、システム構造（システムアーキテクチャ）全体に、どのように組み込んで行くかをモデリング実習で学んでいく。",
