      "themeAndGoals": "１．コンピュータの仕組みとプログラミングの基礎知識を修得できる。\n２．データ構造、プログラム言語の基礎知識を修得できる。\n３．アルゴリズム設計の基礎知識を修得できる。\n４．プログラム作成さらにはシステム設計の基礎知識を修得できる。",
      "officialOverview": "プログラム作成における使用メモリ量と計算時間の見積りのための理論的基礎であるデータ構造を学習し、アルゴリズムの設計と解析の基礎知識を習得することが目的である。スタックやキュー、配列などの基本的データ構造や、貪欲法、分割統治法、動的計画法などの基本的なアルゴリズムの設計手法を学ぶ。フローチャートを使ってアルゴリズムをモデル化し、実例・演習を用いながら様々な角度から逐次アルゴリズム設計手法を学ぶ。",
      "teachingMethod": "■ 講義　■ 演習　□ 実験・実習・実技",
