      "themeAndGoals": "1.情報ネットワークの基礎を理解する。\n2.インターネットの動作原理を理解する。\n3.情報セキュリティーを体系的に理解する。\n4.具体的な情報セキュリティマネジメントについて理解する。",
      "officialOverview": "本講義は現在の情報化社会において中核となっている、情報ネットワークと情報セキュリティについて基礎的・体系的に学び、理解することを目的とする。\n（情報ネットワーク）インターネットを中心とした情報通信ネットワークが幅広く利用されている現在において、Society 5.0の実現に向けて家電やモバイル端末などがネットワークへの接続を前提としたものとなり、ネットワークが生活の基盤になりつつある。そこで、ネットワークの基本的な知識・技術を知ることは必要不可欠であるため、ネットワークの構成や通信に必要となるプロトコル、通信サービスなどを学び、それらを体系的に理解することを目標とする。\n（情報セキュリティ）インターネットを中核とするITが企業の活動に深く浸透することに伴い、適切な情報セキュリティの確保は企業が有効かつ効率的に活動するにあたっての前提条件となってきていることを踏まえ、情報セキュリティを体系的に把握する。情報セキュリティにおける脅威や脆弱性、最新の技術動向、関連法制度、関連する情報システムなどを学習し、具体的な情報セキュリティマネジメントについて理解することを目標とする。",
      "teachingMethod": "■ 講義　□ 演習　□ 実験・実習・実技",
