      "officialOverview": "皆さんは、どこか知らない場所に行くときなどに地図アプリの経路探索を使ったことがありますか。アプリの中には、様々な経路の中からもっとも「良い」経路を計算するソフトウエアが組み込まれており、距離の短い、あるいは費用の安い、乗り換え回数の少ないなど「良さ」の基準に応じた「最適な」答えを計算しています。このような「最適な」決定を導き出すソフトウエアを開発するためには、「最適化モデリング」と呼ばれる考え方が必要です。最適化モデリングは、製造や物流をはじめ、マーケティングやスポーツなど幅広い分野で活用されている考え方です。この講義では、「最適化モデリング」を実際の例を使いながら理解し、プログラミングの演習を通じ実際に活用できる技術を学びます。\n毎回の授業ではPCを用いた演習を行います。そのため、毎回の講義ではPCが必要となります。また、レポート課題に取り組むためにもPCが必要となります。試験（課題）と毎回の小テストの提出状況と内容の出来を成績評価とします。",
      "teachingMethod": "■ 講義　■ 演習　□ 実験・実習・実技",
