      "officialOverview": "インターネットマーケティングやCRM（カスタマーリレーションシップマネジメント）に関する講義である。Python入門やAI・機械学習基礎等を学習した受講生を対象に、実社会におけるインターネットマーケティング分野への応用や事例について学ぶ。\n講義は主にオンデマンド形式とオンライン形式で実施。座学だけでなく、プログラミング演習の両方を行う。座学においては、インターネットマーケティングの概要・理論・手法・事例を学ぶ。また顧客分析に関連して、CRMやデータベースを用いたカスタマーへ施策についての解説を行い、サンプルデータを用いながらデータ加工・顧客分析・分析結果の評価等、実践に近い方法で授業を進め、理論とプログラミングを修得する。",
