      "themeAndGoals": "１．情報科学の理論と技術を駆使して、高次元データを収集・処理するための知識と能力の獲得。\n２．実データを効率的に処理するためのプログラミング能力の獲得。\n３．多様化・複雑化した情報社会における課題に対して、最適なソリューションを導く能力の獲得。",
      "officialOverview": "専門ゼミは卒業論文を作成するための準備として位置付けられ、担当教員の指導の下、文献検索や論文・専門書の輪読、実データの分析や必要なプログラミングについて学ぶ。専門ゼミ１では、受講生は興味を持った研究トピックに関連する論文・専門書を読み、ディスカッションを通して卒業論文の執筆につながる基礎知識やスキルを習得する。加えて、実社会での実装例を学びながら、それらの重要性と社会的な必要性を理解する。文献講読では、①要点、②評価、③語句説明等を含めたレジュメを作成し報告を行う。報告者以外の受講生もディスカッションに参加し、質問や意見を述べて理解を深める。",
