      "summary": "教育・子ども・学校とは何かを問い直し、西洋と日本の教育思想や歴史を学び、哲学的な視点から現代の教育課題や実践を検討する。教育の理念と変遷を現在の学校状況に結び付け、教育の意義や課題について根拠をもって思索する力を身につける。",
