        "模擬授業（情報社会の問題解決）の実施と省察：情報社会の問題解決について学ぶ模擬授業の実施と省察",
        "模擬授業（コミュニケーションと情報デザイン）の検討：コミュニケーションと情報デザインについて学ぶ学習指導について検討",
        "模擬授業（コミュニケーションと情報デザイン）の実施と省察：コミュニケーションと情報デザインについて学ぶ模擬授業の実施と省察",
