      "officialOverview": "本講義は、中学校教員免許状取得に必要な教職課程科目のうち、「教育の方法及び技術」に該当する。本講義では、①授業づくりの方法論、②授業実践の技術、③授業や子どもをとりまく問題状況、④教師の権利と責任、の4つの内容を中心的に扱う。これらの学習を通して、これからの社会を担う子どもたちに求められる資質・能力を育成するために必要な教育の方法、教育の技術、情報機器および教材の活用に関する基礎的な知識・技能を身につける。あわせて、教育方法の理論を活用して、教師は教科指導を中核として子どもの成長にどのように関わることができるかについて考えていく。\n【アクティブラーニングについて】\n授業の一部にアクティブラーニング（グループワーク）を含む。",
      "teachingMethod": "■ 講義　■ 演習　□ 実験・実習・実技",
