      "officialOverview": "教育相談は、生徒が自己理解を深めたり好ましい人間関係を築いたりしながら、集団の中で適応的に生活する力を育み、個性の伸長や人格の成長を支援する教育活動である。「教育相談Ⅰ」では、中学生（児童期後期から青年期前期）の発達の状況に即しつつ、個々の心理的特質や教育的課題を適切に捉え、支援するために必要な基礎的知識（カウンセリングの意義、理論や技法に関する基礎的知識を含む）を学ぶことが主眼となる。また、それらを基本とした事例検討を通して、中学校におけるアセスメント及び対応策についても理解し、その応用についても学ぶ。",
