        "特別支援教育の歴史 特別支援教育の対象幼児・児童・生徒 【個別の支援計画】 事前・事後学習（240分） ・個別の教育支援計画の作成",
        "視覚障害領域①： 視覚障害者の心理・生理・病理 （弱視・盲） 【視覚障害シミュレーション体験】 事前・事後学習（240分） ・視覚障害シミュレーションで感じた困難感についてまとめ",
        "視覚障害領域②： 視覚障害者の教育法 （弱視・盲） 【点字版及び白杖体験】 事前・事後学習（240分） ・点字版使用の気づきについてまとめる ・白杖使用で気づいた歩行の困難感についてまとめる",
        "聴覚障害領域①： 聴覚障害者の心理・生理・病理 （難聴・ろう） 【オージオグラム】 事前・事後学習（240分） ・聴覚障害者の感じる困難感についてまとめる",
        "聴覚障害領域②： 聴覚障害者の教育法 （難聴・ろう） 【手話ビデオ教材】 事前・事後学習（240分） ・デフコミュニティについて調べまとめる",
        "知的障害領域①： 知的障害者の心理・生理・病理 【知能検査】 事前・事後学習（240分） ・知的障碍者の学習上の困難感について調べまとめる",
        "知的障害領域②： 知的障害者の教育法 【事例検討・グループディスカッション】 事前・事後学習（240分） ・事例検討の際に出た議論についてまとめる。",
